// Calculate the date range for the past 7 days
const now = new Date();
const endDate = new Date(now);
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 7);

const fmt = (d) => d.toISOString();
const fmtReadable = (d) =>
  d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

return [{
  json: {
    since: fmt(startDate),
    until: fmt(endDate),
    weekLabel: `${fmtReadable(startDate)} → ${fmtReadable(endDate)}`
  }
}];

// Safely gather data from all upstream nodes
const config = $('⚙️ Configuration').item.json;
const dateRange = $('📅 Calculate Date Range').item.json;

// Collect raw commits (may be array response or single item)
let rawCommits = [];
try {
  const commitItems = $('📝 Get Commits').all();
  commitItems.forEach(item => {
    if (Array.isArray(item.json)) {
      rawCommits = rawCommits.concat(item.json);
    } else {
      rawCommits.push(item.json);
    }
  });
} catch(e) { rawCommits = []; }

// Collect raw issues
let rawIssues = [];
try {
  const issueItems = $('🐛 Get Closed Issues').all();
  issueItems.forEach(item => {
    if (Array.isArray(item.json)) {
      rawIssues = rawIssues.concat(item.json);
    } else {
      rawIssues.push(item.json);
    }
  });
} catch(e) { rawIssues = []; }

// Collect raw PRs
let rawPRs = [];
try {
  const prItems = $('🔀 Get Merged PRs').all();
  prItems.forEach(item => {
    if (Array.isArray(item.json)) {
      rawPRs = rawPRs.concat(item.json);
    } else {
      rawPRs.push(item.json);
    }
  });
} catch(e) { rawPRs = []; }

// Parse date boundaries
const since = new Date(dateRange.since);
const until = new Date(dateRange.until);

// Filter and format commits
const commits = rawCommits
  .filter(c => c && c.commit)
  .filter(c => {
    const d = new Date(c.commit?.author?.date);
    return d >= since && d <= until;
  })
  .map(c => ({
    sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
    message: c.commit?.message?.split('\n')[0] || '(no message)',
    author: c.commit?.author?.name || c.author?.login || 'unknown',
    date: c.commit?.author?.date || ''
  }));

// Filter and format issues (exclude PRs from issues endpoint)
const issues = rawIssues
  .filter(i => i && !i.pull_request)
  .filter(i => {
    if (!i.closed_at) return false;
    const d = new Date(i.closed_at);
    return d >= since && d <= until;
  })
  .map(i => ({
    number: i.number,
    title: i.title || '(no title)',
    closedBy: i.user?.login || 'unknown',
    closedAt: i.closed_at || '',
    labels: (i.labels || []).map(l => l.name).join(', ')
  }));

// Filter merged PRs within the date range
const mergedPRs = rawPRs
  .filter(pr => pr && pr.merged_at !== null && pr.merged_at !== undefined)
  .filter(pr => {
    const d = new Date(pr.merged_at);
    return d >= since && d <= until;
  })
  .map(pr => ({
    number: pr.number,
    title: pr.title || '(no title)',
    author: pr.user?.login || 'unknown',
    mergedAt: pr.merged_at || '',
    body: (pr.body || '').substring(0, 200)
  }));

// Build Claude prompt based on language
const langInstruction = config.LANGUAGE === 'FR'
  ? 'Répondez UNIQUEMENT en français.'
  : 'Respond ONLY in English.';

const promptContent = `You are a senior engineering lead writing a weekly development digest.
${langInstruction}

Repository: ${config.GITHUB_OWNER}/${config.GITHUB_REPO}
Report period: ${dateRange.weekLabel}

## Raw Activity Data

### Commits (${commits.length} total)
${commits.length === 0 ? 'No commits this week.' : commits.map(c => `• [${c.sha}] ${c.message} — ${c.author}`).join('\n')}

### Closed Issues (${issues.length} total)
${issues.length === 0 ? 'No issues closed this week.' : issues.map(i => `• #${i.number}: ${i.title} (closed by ${i.closedBy}${i.labels ? ', labels: ' + i.labels : ''})`).join('\n')}

### Merged Pull Requests (${mergedPRs.length} total)
${mergedPRs.length === 0 ? 'No PRs merged this week.' : mergedPRs.map(pr => `• #${pr.number}: ${pr.title} by @${pr.author}`).join('\n')}

---

Generate a structured, engaging weekly summary that:
1. Starts with a brief executive headline (1–2 sentences)
2. Groups related work into logical themes (e.g., features, bug fixes, refactoring)
3. Highlights the 2–3 most impactful changes
4. Notes any patterns or concerns (e.g., many bug fixes may signal instability)
5. Ends with a short forward-looking sentence

Format for Discord: use **bold**, emojis (✅ 🔀 🐛 🚀), and section headers with --- separators.
Keep the total length under 1800 characters so it fits in one Discord message.`;

return [{
  json: {
    repo: `${config.GITHUB_OWNER}/${config.GITHUB_REPO}`,
    weekLabel: dateRange.weekLabel,
    language: config.LANGUAGE,
    discordWebhook: config.DISCORD_WEBHOOK_URL,
    claudeApiKey: config.CLAUDE_API_KEY,
    stats: {
      commits: commits.length,
      issues: issues.length,
      prs: mergedPRs.length
    },
    promptContent
  }
}];

// Extract text from Claude's response and build Discord payload
const claudeResponse = $json;
const prevData = $('🧠 Aggregate & Build Prompt').item.json;

const summaryText = claudeResponse?.content?.[0]?.text ||
  '⚠️ Claude returned no content. Please check your API key and model name.';

return [{
  json: {
    discordWebhook: prevData.discordWebhook,
    discordPayload: {
      username: '📊 GitHub Weekly Summary Bot',
      avatar_url: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
      embeds: [
        {
          title: `📅 Weekly Dev Summary: ${prevData.repo}`,
          description: summaryText.substring(0, 4096),
          color: 5814783,
          fields: [
            {
              name: '📝 Commits',
              value: String(prevData.stats.commits),
              inline: true
            },
            {
              name: '🐛 Issues Closed',
              value: String(prevData.stats.issues),
              inline: true
            },
            {
              name: '🔀 PRs Merged',
              value: String(prevData.stats.prs),
              inline: true
            }
          ],
          footer: {
            text: `Period: ${prevData.weekLabel} • Language: ${prevData.language} • Powered by Claude claude-sonnet-4-20250514`
          },
          timestamp: new Date().toISOString()
        }
      ]
    }
  }
}];
